import sys


_HEX_VALUES = {c: i for i, c in enumerate("0123456789abcdefABCDEF")}


def parse_json(text: str) -> object:
    try:
        sys.set_int_max_str_digits(0)
    except (AttributeError, ValueError):
        pass

    t = text
    n = len(t)

    def skip_ws(i: int) -> int:
        while i < n:
            c = t[i]
            if c == " " or c == "\t" or c == "\n" or c == "\r":
                i += 1
            else:
                break
        return i

    def to_decimal_int(start: int, end: int) -> int:
        # Converts a signed decimal integer substring [start, end) to int.
        # This avoids relying on int(str) for extremely long decimal literals.
        neg = False
        if t[start] == "-":
            neg = True
            start += 1

        digits_len = end - start

        if digits_len <= 4096:
            value = int(t[start:end])
            return -value if neg else value

        pow10_cache = {1: 10}

        def pow10(length: int) -> int:
            if length <= 1:
                return 1
            if length in pow10_cache:
                return pow10_cache[length]

            half = length // 2
            p = pow10(half)
            result = p * p
            if length % 2:
                result *= 10

            pow10_cache[length] = result
            return result

        def convert(left: int, right: int) -> int:
            length = right - left
            if length <= 4096:
                return int(t[left:right])

            mid = (left + right) // 2
            left_value = convert(left, mid)
            right_len = right - mid
            right_value = convert(mid, right)
            return left_value * pow10(right_len) + right_value

        value = convert(start, end)
        return -value if neg else value

    def parse_string(i: int) -> tuple[str, int]:
        # Parses a JSON string value starting at text[i] == '"'.
        i += 1
        parts = []

        while i < n:
            start = i
            while i < n:
                c = t[i]

                if c == '"':
                    if i > start:
                        parts.append(t[start:i])
                    return "".join(parts), i + 1

                if c == "\\":
                    if i > start:
                        parts.append(t[start:i])

                    i += 1
                    if i >= n:
                        raise ValueError("invalid string escape")

                    e = t[i]
                    i += 1

                    if e == '"':
                        parts.append('"')
                    elif e == "\\":
                        parts.append("\\")
                    elif e == "/":
                        parts.append("/")
                    elif e == "b":
                        parts.append("\b")
                    elif e == "f":
                        parts.append("\f")
                    elif e == "n":
                        parts.append("\n")
                    elif e == "r":
                        parts.append("\r")
                    elif e == "t":
                        parts.append("\t")
                    elif e == "u":
                        if i + 4 > n:
                            raise ValueError("invalid Unicode escape")

                        h0 = _HEX_VALUES.get(t[i])
                        if h0 is None:
                            raise ValueError("invalid Unicode escape")
                        h1 = _HEX_VALUES.get(t[i + 1])
                        if h1 is None:
                            raise ValueError("invalid Unicode escape")
                        h2 = _HEX_VALUES.get(t[i + 2])
                        if h2 is None:
                            raise ValueError("invalid Unicode escape")
                        h3 = _HEX_VALUES.get(t[i + 3])
                        if h3 is None:
                            raise ValueError("invalid Unicode escape")

                        cp = (h0 << 12) | (h1 << 8) | (h2 << 4) | h3
                        i += 4

                        if 0xD800 <= cp <= 0xDBFF:
                            if i + 5 >= n or t[i] != "\\" or t[i + 1] != "u":
                                raise ValueError("invalid Unicode surrogate pair")

                            lo0 = _HEX_VALUES.get(t[i + 2])
                            if lo0 is None:
                                raise ValueError("invalid Unicode surrogate pair")
                            lo1 = _HEX_VALUES.get(t[i + 3])
                            if lo1 is None:
                                raise ValueError("invalid Unicode surrogate pair")
                            lo2 = _HEX_VALUES.get(t[i + 4])
                            if lo2 is None:
                                raise ValueError("invalid Unicode surrogate pair")
                            lo3 = _HEX_VALUES.get(t[i + 5])
                            if lo3 is None:
                                raise ValueError("invalid Unicode surrogate pair")

                            low = (lo0 << 12) | (lo1 << 8) | (lo2 << 4) | lo3
                            if low < 0xDC00 or low > 0xDFFF:
                                raise ValueError("invalid Unicode surrogate pair")

                            combined = 0x10000 + ((cp - 0xD800) << 10) + (low - 0xDC00)
                            parts.append(chr(combined))
                            i += 6

                        elif 0xDC00 <= cp <= 0xDFFF:
                            raise ValueError("invalid Unicode escape")

                        else:
                            parts.append(chr(cp))

                    else:
                        raise ValueError("invalid string escape")

                    start = i
                    continue

                cp = ord(c)
                if cp < 32 or (0xD800 <= cp <= 0xDFFF):
                    raise ValueError("invalid string character")

                i += 1

            if i > start:
                parts.append(t[start:i])

            raise ValueError("invalid string")

        raise ValueError("invalid string")

    def parse_number(i: int) -> tuple[object, int]:
        # Parses a strict JSON number starting at text[i].
        start = i
        c = t[i]

        if c == "-":
            i += 1
            if i >= n:
                raise ValueError("invalid number")
            c = t[i]

        if c == "0":
            i += 1
        elif "0" <= c <= "9":
            i += 1
            while i < n:
                c = t[i]
                if "0" <= c <= "9":
                    i += 1
                else:
                    break
        else:
            raise ValueError("invalid number")

        has_fraction_or_exponent = False

        if i < n and t[i] == ".":
            i += 1
            if i >= n:
                raise ValueError("invalid number")

            c = t[i]
            if c < "0" or c > "9":
                raise ValueError("invalid number")

            i += 1
            while i < n:
                c = t[i]
                if "0" <= c <= "9":
                    i += 1
                else:
                    break

            has_fraction_or_exponent = True

        if i < n and (t[i] == "e" or t[i] == "E"):
            i += 1

            if i < n and (t[i] == "+" or t[i] == "-"):
                i += 1

            if i >= n:
                raise ValueError("invalid number")

            c = t[i]
            if c < "0" or c > "9":
                raise ValueError("invalid number")

            i += 1
            while i < n:
                c = t[i]
                if "0" <= c <= "9":
                    i += 1
                else:
                    break

            has_fraction_or_exponent = True

        literal = t[start:i]

        if not has_fraction_or_exponent:
            return to_decimal_int(start, i), i

        try:
            return float(literal), i
        except OverflowError:
            # JSON numbers may overflow Python floats, in which case the
            # intended IEEE-754 value is positive or negative infinity.
            core = literal.split("e", 1)[0].split("E", 1)[0]
            nonzero = False
            for ch in core:
                if "0" <= ch <= "9" and ch != "0":
                    nonzero = True
                    break

            if not nonzero:
                return -0.0 if literal[0] == "-" else 0.0

            return float("-inf") if literal[0] == "-" else float("inf")

    stack = []
    root_value = None
    done = False
    i = skip_ws(0)

    if i >= n:
        raise ValueError("empty input")

    def finish(value: object) -> None:
        nonlocal i, root_value, done

        while True:
            if not stack:
                root_value = value
                done = True
                return

            frame = stack[-1]

            if frame[0]:
                # Array context.
                frame[1].append(value)

                i = skip_ws(i)
                if i < n and t[i] == ",":
                    i = skip_ws(i + 1)
                    return

                if i < n and t[i] == "]":
                    i += 1
                    value = frame[1]
                    stack.pop()
                    continue

                raise ValueError("invalid array")

            # Object context.
            phase = frame[4]

            if phase == 0:
                # Finished parsing an object key.
                if value in frame[2]:
                    raise ValueError("duplicate object key")

                frame[2].add(value)
                frame[3] = value
                frame[4] = 1

                i = skip_ws(i)
                if i < n and t[i] == ":":
                    i = skip_ws(i + 1)
                    return

                raise ValueError("invalid object")

            # Finished parsing an object value.
            frame[1][frame[3]] = value

            i = skip_ws(i)
            if i < n and t[i] == ",":
                i = skip_ws(i + 1)
                frame[4] = 0
                return

            if i < n and t[i] == "}":
                i += 1
                value = frame[1]
                stack.pop()
                continue

            raise ValueError("invalid object")

    while not done:
        if i >= n:
            raise ValueError("missing value")

        # In an object, the next value position is always a key.
        if stack and not stack[-1][0] and stack[-1][4] == 0:
            if t[i] != '"':
                raise ValueError("invalid object key")

            value, i = parse_string(i)
            finish(value)
            continue

        c = t[i]

        if c == '"':
            value, i = parse_string(i)
            finish(value)
            continue

        if c == "-" or ("0" <= c <= "9"):
            value, i = parse_number(i)
            finish(value)
            continue

        if c == "[":
            j = skip_ws(i + 1)

            if j < n and t[j] == "]":
                i = j + 1
                finish([])
                continue

            stack.append([True, [], None, None, 0])
            i = j
            continue

        if c == "{":
            j = skip_ws(i + 1)

            if j < n and t[j] == "}":
                i = j + 1
                finish({})
                continue

            stack.append([False, {}, set(), None, 0])
            i = j
            continue

        if t.startswith("true", i):
            i += 4
            finish(True)
            continue

        if t.startswith("false", i):
            i += 5
            finish(False)
            continue

        if t.startswith("null", i):
            i += 4
            finish(None)
            continue

        raise ValueError("invalid JSON value")

    i = skip_ws(i)
    if i != n:
        raise ValueError("trailing input")

    return root_value
